export const getMonster = (key) => MONSTERS.find((m) => m.key === key)
// CR may be a number (0.25) or a fraction string ("1/4") depending on the source data
export const crValue = (cr) => {
  if (typeof cr === 'number') return cr
  const [n, d] = String(cr).split('/').map(Number)
  return d ? n / d : n
}
export const crLabel = (cr) => {
  const v = crValue(cr)
  return v === 0.125 ? '1/8' : v === 0.25 ? '1/4' : v === 0.5 ? '1/2' : `${v}`
}
export const abilityModStr = (score) => {
  const m = Math.floor((score - 10) / 2)
  return `${score} (${m >= 0 ? '+' : ''}${m})`
}
